            add(
                clip.start.saturating_add(clip.duration),
                format!("clip {} end", clip.id),
                &mut ticks,
            );
        }

        ticks.sort_unstable();
        ticks.dedup();

        let mut out = Map::new();
        out.insert(
            "ticks".to_string(),
            Value::Array(ticks.into_iter().map(Value::from).collect()),
        );
        out.insert("labels".to_string(), Value::Object(labels));
        Value::Object(out)
